//! Auto-generated C++ code generation for Polyglot Lab.

use anyhow::Result;
use lab_node_sdk::GraphSpec;
use std::collections::{HashMap, HashSet};

/// Generates `CMakeLists.txt` content.
pub fn generate_cmake_lists(project_name: &str) -> String {
    let safe_name = crate::codegen::sanitize_ident(project_name);
    format!(
        r#"cmake_minimum_required(VERSION 3.20)
project({safe_name} CXX)

set(CMAKE_CXX_STANDARD 20)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

include_directories(include)

add_executable({safe_name} src/main.cpp)
"#
    )
}

/// Generates `include/nodes.hpp` with self-contained implementations of atomic nodes.
pub fn generate_nodes_hpp(used_kinds: &HashSet<&str>) -> String {
    let mut code = String::from(
        r#"// Code generated by Polyglot Lab. DO NOT EDIT.
#pragma once

#include <iostream>
#include <string>
#include <fstream>
#include <sstream>
#include <chrono>
#include <thread>
#include <algorithm>
#include <cctype>
#include <stdexcept>

namespace nodes {

"#,
    );

    if used_kinds.contains("fs_read") {
        code.push_str(
            r#"inline std::string fs_read(const std::string& path) {
    std::cout << "   Reading file: " << path << "\n";
    std::ifstream file(path);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file: " + path);
    }
    std::stringstream buffer;
    buffer << file.rdbuf();
    return buffer.str();
}

"#,
        );
    }

    if used_kinds.contains("fs_write") {
        code.push_str(
            r#"inline int fs_write(const std::string& path, const std::string& content) {
    std::cout << "   Writing to file: " << path << "\n";
    std::ofstream file(path);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file for writing: " + path);
    }
    file << content;
    return static_cast<int>(content.size());
}

"#,
        );
    }

    if used_kinds.contains("log_output") {
        code.push_str(
            r#"template <typename T>
inline void log_output(const T& text) {
    std::cout << "   Log Output: " << text << "\n";
}

"#,
        );
    }

    if used_kinds.contains("text_clean") {
        code.push_str(
            r#"inline std::string text_clean(const std::string& text, bool trim = true, bool collapse = false, bool to_lower = false, bool to_upper = false) {
    if (to_lower && to_upper) {
        throw std::invalid_argument("'to_lower' and 'to_upper' cannot both be true");
    }
    std::string res = text;
    if (trim) {
        size_t start = res.find_first_not_of(" \t\n\r");
        size_t end = res.find_last_not_of(" \t\n\r");
        res = (start == std::string::npos) ? "" : res.substr(start, end - start + 1);
    }
    if (to_lower) {
        std::transform(res.begin(), res.end(), res.begin(), [](unsigned char c) { return std::tolower(c); });
    }
    if (to_upper) {
        std::transform(res.begin(), res.end(), res.begin(), [](unsigned char c) { return std::toupper(c); });
    }
    return res;
}

"#,
        );
    }

    if used_kinds.contains("delay") {
        code.push_str(
            r#"inline void delay(const std::string& duration_str) {
    std::cout << "   Sleeping for " << duration_str << "\n";
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
}

"#,
        );
    }

    if used_kinds.contains("string_to_path") {
        code.push_str(
            r#"inline std::string string_to_path(const std::string& raw) {
    if (raw.empty()) {
        throw std::invalid_argument("Path cannot be empty");
    }
    return raw;
}

"#,
        );
    }

    code.push_str("} // namespace nodes\n");
    code
}

fn cpp_string_literal(value: &str) -> String {
    format!("{value:?}")
}

/// Generates C++ code statement for a single node.
pub fn generate_cpp_node_call(
    node: &lab_node_sdk::NodeInstance,
    graph: &GraphSpec,
    indent: &str,
) -> String {
    let mut out = format!("{indent}// 🚀 Node: '{}' ({})\n", node.id, node.kind);
    let id_ident = crate::codegen::sanitize_ident(&node.id);

    let mut in_edges: HashMap<&str, (&str, &str)> = HashMap::new();
    for edge in &graph.edges {
        if edge.to.node == node.id {
            in_edges.insert(&edge.to.port, (&edge.from.node, &edge.from.port));
        }
    }

    match node.kind.as_str() {
        "fs_read" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                cpp_string_literal(p)
            };
            out.push_str(&format!("{indent}auto {id_ident}_content = nodes::fs_read({path_expr});\n"));
        }
        "fs_write" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                cpp_string_literal(p)
            };
            let content_expr = if let Some(&(src, sport)) = in_edges.get("content") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let c = node.config.get("content").and_then(|v| v.as_str()).unwrap_or("");
                cpp_string_literal(c)
            };
            out.push_str(&format!("{indent}auto {id_ident}_bytes_written = nodes::fs_write({path_expr}, {content_expr});\n"));
        }
        "log_output" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let t = node.config.get("text").and_then(|v| v.as_str()).unwrap_or("");
                cpp_string_literal(t)
            };
            out.push_str(&format!("{indent}nodes::log_output({text_expr});\n"));
        }
        "text_clean" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let t = node.config.get("text").and_then(|v| v.as_str()).unwrap_or("");
                cpp_string_literal(t)
            };
            let trim = if node.config.get("trim").and_then(|v| v.as_bool()).unwrap_or(true) { "true" } else { "false" };
            let collapse = if node.config.get("collapse").and_then(|v| v.as_bool()).unwrap_or(false) { "true" } else { "false" };
            let to_lower = if node.config.get("to_lower").and_then(|v| v.as_bool()).unwrap_or(false) { "true" } else { "false" };
            let to_upper = if node.config.get("to_upper").and_then(|v| v.as_bool()).unwrap_or(false) { "true" } else { "false" };
            out.push_str(&format!("{indent}auto {id_ident}_cleaned = nodes::text_clean({text_expr}, {trim}, {collapse}, {to_lower}, {to_upper});\n"));
        }
        "delay" => {
            let dur_expr = if let Some(&(src, sport)) = in_edges.get("duration") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let d = node.config.get("duration").and_then(|v| v.as_str()).unwrap_or("0ms");
                cpp_string_literal(d)
            };
            out.push_str(&format!("{indent}nodes::delay({dur_expr});\n"));
        }
        "string_to_path" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                cpp_string_literal(p)
            };
            out.push_str(&format!("{indent}auto {id_ident}_path = nodes::string_to_path({path_expr});\n"));
        }
        _ => {}
    }

    out
}

/// Generates `src/main.cpp` with topological execution.
pub fn generate_main_cpp(graph: &GraphSpec, topo_order: &[String]) -> Result<String> {
    let node_map: HashMap<&str, &lab_node_sdk::NodeInstance> =
        graph.nodes.iter().map(|n| (n.id.as_str(), n)).collect();

    let mut body = String::new();
    for id in topo_order {
        if let Some(node) = node_map.get(id.as_str()) {
            body.push_str(&generate_cpp_node_call(node, graph, "    "));
        }
    }

    let code = format!(
        r#"// Code generated by Polyglot Lab. DO NOT EDIT.
#include <iostream>
#include "nodes.hpp"

int main() {{
    std::cout << "🚀 Starting exported C++ application...\n";

{body}
    std::cout << "✅ Application finished successfully!\n";
    return 0;
}}
"#
    );

    Ok(code)
}
